58: func (r routeSlice) Len() int {
59: 	return len(r)
60: }
61: func (r routeSlice) Less(i, j int) bool {
62: 	return r[i].Priority < r[j].Priority
63: }
64: func (r routeSlice) Swap(i, j int) {
65: 	r[i], r[j] = r[j], r[i]
66: }
