74: func (r *router) String() string {
75: 	strs := []string{"ROUTER", "--- V4 ---"}
76: 	for _, route := range r.v4 {
77: 		strs = append(strs, fmt.Sprintf("%+v", *route))
78: 	}
79: 	strs = append(strs, "--- V6 ---")
80: 	for _, route := range r.v6 {
