23: )
24: 
25: var hdrLen = unix.CmsgSpace(0)
26: var auxLen = unix.CmsgSpace(int(unsafe.Sizeof(unix.TpacketAuxdata{})))
27: var timensLen = unix.CmsgSpace(int(unsafe.Sizeof(unix.Timespec{})))
28: var timeLen = unix.CmsgSpace(int(unsafe.Sizeof(unix.Timeval{})))
29: 
30: func htons(data uint16) uint16 { return data<<8 | data>>8 }
31: 
32: // EthernetHandle holds shared buffers and file descriptor of af_packet socket
33: type EthernetHandle struct {
34: 	fd     int
35: 	buffer []byte
36: 	oob    []byte
37: 	ancil  []interface{}
38: 	mu     sync.Mutex
39: 	intf   int
40: 	addr   net.HardwareAddr
41: }
42: 
43: // readOne reads a packet from the handle and returns a capture info + vlan info
44: func (h *EthernetHandle) readOne() (ci gopacket.CaptureInfo, vlan int, haveVlan bool, err error) {
45: 	// we could use unix.Recvmsg, but that does a memory allocation (for the returned sockaddr) :(
46: 	var msg unix.Msghdr
47: 	var sa unix.RawSockaddrLinklayer
48: 
49: 	msg.Name = (*byte)(unsafe.Pointer(&sa))
50: 	msg.Namelen = uint32(unsafe.Sizeof(sa))
51: 
52: 	var iov unix.Iovec
53: 	if len(h.buffer) > 0 {
54: 		iov.Base = &h.buffer[0]
55: 		iov.SetLen(len(h.buffer))
56: 	}
57: 	msg.Iov = &iov
58: 	msg.Iovlen = 1
59: 
60: 	if len(h.oob) > 0 {
61: 		msg.Control = &h.oob[0]
62: 		msg.SetControllen(len(h.oob))
63: 	}
64: 
65: 	// use msg_trunc so we know packet size without auxdata, which might be missing
66: 	n, _, e := syscall.Syscall(unix.SYS_RECVMSG, uintptr(h.fd), uintptr(unsafe.Pointer(&msg)), uintptr(unix.MSG_TRUNC))
67: 
68: 	if e != 0 {
69: 		return gopacket.CaptureInfo{}, 0, false, fmt.Errorf("couldn't read packet: %s", e)
70: 	}
71: 
72: 	if sa.Family == unix.AF_PACKET {
73: 		ci.InterfaceIndex = int(sa.Ifindex)
74: 	} else {
75: 		ci.InterfaceIndex = h.intf
